import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import supertest from "supertest";
import { createApp } from "../server/app";
import { MemorySessions } from "../server/sessions";
import { fixtureTransport, testConfig, testIdentity } from "./fixtures";

// Generated by the real Core ASGI handlers from labelled synthetic inputs.
// The Python parity command checks these files byte-for-byte; never regenerate
// them by parsing and serializing their int64 source rows in JavaScript.
const reportFixture = JSON.parse(
  readFileSync(
    new URL("./browser/fixtures/care-report.synthetic.json", import.meta.url),
    "utf8",
  ),
);
const trendFixture = JSON.parse(
  readFileSync(
    new URL("./browser/fixtures/care-trends.synthetic.json", import.meta.url),
    "utf8",
  ),
);

describe("Core caregiver DTOs through the authenticated gateway", () => {
  it("preserves report, series and trend contracts after lossless upstream parsing", async () => {
    const fixture = fixtureTransport({
      ...testIdentity,
      level: 30,
      userTypeId: "30",
    });
    const subject = reportFixture.report.subjectId;
    const reportId = reportFixture.report.id;
    const replies = new Map<string, unknown>([
      [
        `/v1/care/subjects/${subject}/reports/${reportId}`,
        reportFixture.report,
      ],
      [
        `/v1/care/subjects/${subject}/reports/${reportId}/series`,
        reportFixture.series,
      ],
      [`/v1/care/subjects/${subject}/trends`, trendFixture.trends],
    ]);
    const careCalls: string[] = [];
    const app = createApp(
      { ...testConfig, caregiverUserTypeIds: new Set(["30"]) },
      new MemorySessions(),
      async (input, init) => {
        const url = new URL(String(input));
        const reply = replies.get(url.pathname);
        if (reply) {
          careCalls.push(url.pathname);
          expect(init?.method ?? "GET").toBe("GET");
          expect(new Headers(init?.headers).has("Token")).toBe(true);
          return Response.json({ data: reply });
        }
        return fixture.transport(input, init);
      },
    );
    const api = supertest.agent(app);
    const login = await api
      .post("/api/session/login")
      .set("Origin", testConfig.publicOrigin)
      .send({ login: "synthetic", password: "test password" });
    expect(login.status).toBe(200);
    expect(login.body.identity.caregiverReadOnly).toBe(true);
    for (const [upstreamPath, dto] of replies) {
      const response = await api.get(upstreamPath.replace("/v1/", "/api/"));
      expect(response.status).toBe(200);
      expect(response.body).toEqual({ data: dto });
    }
    expect(careCalls).toHaveLength(3);

    // No generic report-file proxy or write route is introduced.
    for (const suffix of ["download", "file", "pdf"]) {
      const response = await api.get(
        `/api/care/subjects/${subject}/reports/${reportId}/${suffix}`,
      );
      expect(response.status).toBe(404);
      expect(response.body.data).toBeUndefined();
    }
    const write = await api
      .post(`/api/care/subjects/${subject}/reports/${reportId}`)
      .set("Origin", testConfig.publicOrigin)
      .set("X-CSRF-Token", login.body.csrf)
      .send({ enabled: true });
    expect(write.status).toBe(404);
    expect(careCalls).toHaveLength(3);
  });
});
